              { vals: ["游泳课纪律：下水前不许问为什么", "教练说「问了就加练」，且在整个课程期间从不解释任何动作的理由"], cells: { "是否构成灌输": "倾向于是（但在技能领域需要谨慎判断）", "主要依据哪条判据": "方法判据：理由永久不被交付", "这条判据在此处的困难": "技能训练常需要先做后懂，所以「先做」不构成灌输；判定点在「永久不解释」这一条上。这也提醒：灌输概念主要适用于信念，用在纯技能上要格外小心。" }, note: "最后这一行是本讲的边界案例。若你认为技能领域根本谈不上灌输，请写出你的理由——那等于主张灌输是一个只适用于信念的概念。" }
