          back: "字面是「自己给自己立法」（希腊文 auto-nomos）：行动与信念由自己的理性判断来定，而不由外部权威或未经审视的欲望推着走。康德《答「什么是启蒙」》（1784）给了它教育版本：脱离自己所加之于自己的不成熟状态。迪尔登把它拆成三层（标准重构）：不被权威牵着走、对自己的选择有所理解、能按自己的价值判断行动。",
