          scheme: "非形式（以「无法判断」为理由的家长主义论证）",
          valid: true,
          sound: false,
          gap: "最弱的是 P3：它把「当事人无法作出有意义的判断」直接兑换成「可以替他决定」，而这条原则一旦普遍化，就要为一切家长主义安排开门——从强制用药到禁止恋爱都可能被同一形式辩护。会推翻它的情形：只要举出一个「当事人不能判断、但替他决定明显是支配」的例子（如为了家庭荣誉替他决定婚姻），P3 的原版就站不住。要救这个论证，必须把 P3 换成带限定的版本：临时性、以扩展当事人未来的选择范围为目标、理由可被交付并在条件具备时接受检验——这三条限定正是本讲从卢梭与拉兹那里提炼出的分界线。P2 是第二可疑的前提：儿童并非对任何事情都不能作有意义的判断，很多研究显示他们在与其生活直接相关的事务上有稳定的偏好与判断力。",
          hint: "问自己：这一步「他判断不了，所以我来定」有没有边界？边界在哪里？"
