      writing: [
        {
          id: "philo-education-2-w1",
          title: "小论文：为一次「不可检讨的教学」作最强化辩护，再反驳它",
          prompt: "写一篇 800–1000 字的论文，分两半。前半：选一个你认为最可能为「不可检讨的教学」辩护的立场（例如：某些共同价值与基本纪律必须先被接受，之后才谈得上讨论；或：儿童的判断力有限，过早开放讨论会让他们被最强的声音带走），按最强版本把它写成论证，包含至少两条前提与一条结论，并说明它对哪些情形成立。后半：你自己反驳这个论证，指出最弱的那条前提，并说明什么证据或反例会推翻它。全文的最后一段必须回答：在什么条件下，你可以接受一次「暂时不许质疑」的教学。不要写成两面都对的骑墙文——结尾要有一个明确的判据。",
          considerations: [
            "先把辩护写成论证再反驳：如果前半只写成一段感想，后半的反驳就没有靶子，整篇文章会退化成表态。",
            "分清「暂时」与「永久」：几乎所有可辩护的辩护词都建立在时间结构上；如果你的辩护不涉及时间，它多半在主张永久不可质疑，那要承担更重的举证责任。",
            "注意你自己提出的判据要能被用来查账：写出「谁在什么时候把理由交付给谁」，而不是「教师应当真诚」。",
            "想一想反驳的代价：如果你的判据要求任何教学都必须当场允许质疑，那么你如何解释幼儿学语言、儿童学交通规则这类无法当场讨论的场合？"
          ],
          outline: [
            { s: "引言：把争点定住", d: "一句话说明你要辩护的是哪一类教学（例如：涉及基本安全与共同规则、且学习者尚不具备评估能力的场合），并给出你的论题句。" },
            { s: "前半第一节：最强辩护", d: "写出两条以上前提与结论，说明这个立场对什么情形有解释力。用钢人原则写，不要写成容易被推翻的弱版本。" },
            { s: "前半第二节：辩护的边界", d: "主动说出这个辩护不适用于哪些情形，显示你清楚它的射程。" },
            { s: "后半：反驳", d: "指出最弱前提，给出反例或证据，并说明这个反例为什么不是特例。" },
            { s: "结论：你的判据", d: "用两三句写出你在什么条件下可以接受暂时不许质疑的教学，并承认这条判据会误判什么。" }
          ],
          rubric: [
            { k: "辩护达到最强版本", w: "30%", d: "前半的论证有清楚的前提与结论，且不是稻草人；读者能看出你确实理解这一方为什么有人支持。" },
            { k: "反驳击中要害", w: "25%", d: "明确指出最弱前提，并给出反例或证据；不是换个角度重申自己的立场。" },
            { k: "时间结构与判据可操作", w: "20%", d: "结论中的判据写明理由何时、由谁、以什么方式交付，可被用来核查一个真实课堂。" },
            { k: "术语与引文规范", w: "15%", d: "灌输、自主、可检讨性等术语首次出现给原文并解释；引用标明出处，概述与引文分开标注。" },
            { k: "结构清楚、无骑墙", w: "10%", d: "五个部分各司其职，结尾给出明确判据；不出现「两边都有道理」这类没有承担判断的收尾。" }
          ],
          sample: "以下为范例片段，不是标准答案：\n\n「我要为之辩护的是这样一类教学：内容涉及基本安全与共同规则，学习者尚不具备评估它的能力，而教师承诺在条件具备时交出理由。这个立场的最强版本不是『孩子不懂事所以听大人的』，而是：某些能力本身是参与讨论的前提，在前提尚未具备时开放讨论，实际效果是让声音最大的人获胜——这不是自主，而是另一种被支配。它成立的范围很窄：只覆盖那些『不会等太久』且『理由确实存在』的内容。它不适用于任何有争议的价值命题，因为在那些问题上，不讨论并不产生能力，只产生服从。」"
          ,
          pitfalls: [
            "前半写得太弱：为了让后半好反驳，把对方写成「权威主义就是不讲道理」，这样即便赢了也没有推进任何认识。",
            "把「暂时」当万能挡箭牌：如果辩护词里的暂时没有兑现时点，它就是永久，只是听起来温和。",
            "判据写成态度词：出现「应当尊重学生的主体性」这类句子而没有可核查的动作，读者无法用它对任何课堂作判断。",
            "忽略反例的代价：提出严格判据却不承认它会误判某些真实场合（如幼儿学语言），会让判据失去可用性。"
          ]
        }
      ]
