          sample: "以下为范例片段，不是标准答案：\n\n「某校把每周两课时的书法从必修改为选修，把课时让给数学与英语。这个决定的代价是清楚的：所有学生失去了一段共同的书写训练，而书法师资的课时被压缩。支持它的三条理由里，第一条是结构理由（数学课时不足），第二条是工具理由（书法的收益对升学没有贡献，宾语是升学），第三条是认同理由（书法属于本地文化传统）。承重墙在第二条：一旦本校的升学评价方式改变，这条理由会反向支持保留书法，所以它不能单独承担正当化。真正对立的一步不是「书法重不重要」，而是那个可比性前提——我们是否有能力比较书法与数学的收益。」"
