            "只写理由不写代价：一条没有代价的课程主张等于没有对手，读者无法判断你到底在改变什么。",
            "用「研究表明」代替具体证据：教育研究结论差别很大，写清是哪类研究、测量的是什么，否则这句话只会减分。",
            "对立面写成稻草人：把反对者写成「不重视学生」，会让第三节失去作用，也让你无法知道自己的论证是否真的更强。"
