          gap: "最弱的是 P2：它把「新信息必须与学习者已有结构发生联系才能被掌握」这一描述性命题，偷换成「讲授无法让学生获得知识」这一几乎全称的否定，并在结论里进一步换成规范命题「不应当讲授」。三重滑动都发生在这一条前提里。会推翻它的情形：奥苏贝尔的有意义接受学习就是直接反例——教师把完整组织好的内容讲给学生，只要它落进学生已有的结构，学习同样是有意义的；专长逆转效应进一步显示，对新手而言更多的显式指导反而更好。要救这个论证，只能把 P2 改成弱版本「与已有结构脱钩的讲授无法带来理解」，但这样一来结论就必须同样改弱，改弱后的结论不再支持「不应当直接讲授」，而只支持「讲授必须与学生已有结构衔接」——后者几乎没有人反对。",
          hint: "数一数这条推理里有几处滑动：机制、效果、规范，各滑了一次。"
