          prompt: "选一种你亲身经历过的教学法（可以是背诵默写、题海训练、项目式学习、翻转课堂、讨论课、或某位老师的独特做法），写一篇 800–1000 字的论文。要求：① 先用不超过 150 字描述这种教学法的具体做法，包括它在什么内容、什么阶段使用；② 用迁移性、可解释性、可修正性、生成性四条判据逐条评估它，每条都要给出你亲身经历中的具体证据（做过什么题、被要求做什么、结果怎样）；③ 指出这种教学法在什么条件下有效、在什么条件下失效（例如学习者先备知识不同、内容类型不同）；④ 回应一个反驳：如果有人拿本讲引用的实证研究（如阿尔菲耶里 2011 年的元分析或专长逆转效应）说你的评价不成立，你会怎么回答？⑤ 最后写一句判据式结论：在什么条件下你会推荐这种教学法，在什么条件下不会。",
